function addBonusPuzzleObject(i){const objects={0:{id:'wall-words',name:'scratched stone',pos:[-5.4,2.1,-6.35],size:[1.2,1.1,.25],color:0x69251f},1:{id:'bedside-drawer',name:'alarm clock mechanism',pos:[5.7,1.7,-4.35],size:[1.2,1,.55],color:0x8b663b},2:{id:'ritual-marks',name:'marked cabinet',pos:[-4.1,1.65,-5.15],size:[1.4,.7,.35],color:0x67332b},3:{id:'dated-lockbox',name:'dated lockbox',pos:[-4.8,1.35,-5.75],size:[1,.5,.5],color:0x756548},4:{id:'candle-directions',name:'pump diagram',pos:[4.8,2,-6.1],size:[1.2,1.4,.25],color:0x5d756c},5:{id:'tool-pattern',name:'tool cabinet',pos:[0,2.3,-6.25],size:[2.1,1.2,.35],color:0x5e4d3d}};const item=objects[i];if(!item)return;const object=box(item.name,item.pos,item.size,item.color);object.material.emissive.setHex(item.color);object.material.emissiveIntensity=.22;interactive(item.pos,item.size.map(value=>value+.35),i,'bonus',item.id)}

