function chooseMovingWalls(random){const candidates=[];for(let y=2;y<MAZE_SIZE-2;y++)for(let x=2;x<MAZE_SIZE-2;x++)if(mazeGrid[y][x]===1){const horizontal=mazeGrid[y][x-1]===0&&mazeGrid[y][x+1]===0,vertical=mazeGrid[y-1][x]===0&&mazeGrid[y+1][x]===0;if(horizontal||vertical)candidates.push([x,y])}candidates.sort(()=>random()-.5);return candidates.slice(0,60)}
