function updateMovingMaze(dt){if(!movingMazeWalls.length)return;mazeShiftTimer-=dt;mazeBreathTime+=dt;if(mazeShiftTimer<=0){mazeShiftTimer=4;const playerCell=mazeCell(camera.position),chaserCell=rootChaser?mazeCell(rootChaser.position):[-1,-1],cycle=Math.floor(performance.now()/4000);for(let n=0;n<24;n++){const wall=movingMazeWalls[(cycle*24+n)%movingMazeWalls.length],data=wall.userData;if((data.x===playerCell[0]&&data.y===playerCell[1])||(data.x===chaserCell[0]&&data.y===chaserCell[1]))continue;data.open=!data.open;data.targetY=data.open?-5:0;mazeGrid[data.y][data.x]=data.open?0:1}document.querySelector('#prompt').textContent='THE ENTIRE MAZE IS CHANGING — FIND A NEW ROUTE'}movingMazeWalls.forEach((wall,index)=>{wall.position.y=THREE.MathUtils.lerp(wall.position.y,wall.userData.targetY,Math.min(1,dt*2.6));wall.rotation.y=Math.sin(mazeBreathTime*1.7+index*.6)*.035;const pulse=1+Math.sin(mazeBreathTime*2.1+index)*.025;wall.scale.set(pulse,1,pulse)});const label=document.querySelector('#maze-map-panel small');if(label)label.textContent=`LIVING ROOT MAP · SHIFT ${Math.max(1,Math.ceil(mazeShiftTimer))}s`}
function addFalsePassages(random,wanted){const directions=[[1,0],[-1,0],[0,1],[0,-1]],openCells=[];for(let y=2;y<MAZE_SIZE-2;y++)for(let x=2;x<MAZE_SIZE-2;x++)if(mazeGrid[y][x]===0)openCells.push([x,y]);let added=0,attempts=0;while(added<wanted&&attempts++<1500){const [sx,sy]=openCells[Math.floor(random()*openCells.length)],[dx,dy]=directions[Math.floor(random()*4)],length=2+Math.floor(random()*4),carved=[];let x=sx,y=sy;for(let step=0;step<length;step++){x+=dx;y+=dy;if(x<=1||y<=1||x>=MAZE_SIZE-2||y>=MAZE_SIZE-2||mazeGrid[y][x]===0)break;const openNeighbors=directions.filter(([nx,ny])=>mazeGrid[y+ny]?.[x+nx]===0).length;if(openNeighbors!==1)break;mazeGrid[y][x]=0;carved.push([x,y])}if(carved.length>=2){added++;openCells.push(...carved)}else for(const [cx,cy] of carved)mazeGrid[cy][cx]=1}}
