function updateHud(){const r=rooms[room],realitiesSolved=hotelRealities.filter((_,index)=>hotelProgress.has(`reality-solved-${index}`)).length;chapter.textContent=r[0];title.textContent=r[1];description.textContent=r[2];objective.textContent=room===0?`${saved[0]?'The inner door is open.':'Repair the door handle.'} Handle ${handlePieces.size}/3 · Cabin secrets ${cabinSecrets.size}/7`:room===8?hotelRunFloor?`Floor ${hotelRunFloor}, Room ${hotelRunRoom}: search the room and find what unlocks the next door.`:hotelStage===0?'Investigate the service bell, Room 13 key, elevator, and guestbook.':hotelStage===1?`Read the painting and examine the object that does not belong. Patterns solved ${realitiesSolved}/${hotelRealities.length}.`:`${saved[8]?'You checked out.':'Learn the hotel’s rules and reach Floor ∞.'} Impossible room ${Math.min(hotelStage+1,10)}/10`:saved[room]?'The way forward is open.':r[3];count.textContent=`${saved.filter(Boolean).length} / 9`;document.querySelectorAll('#rooms button').forEach((b,i)=>{b.classList.toggle('active',i===room);b.style.display=room===8?(i===8?'':'none'):(i===8?'none':'')});document.querySelector('aside').style.display=room===0?'block':'none'}
function drawMazeMap(){const panel=document.querySelector('#maze-map-panel');if(room!==7||!mazeGrid){panel.style.display='none';return}panel.style.display='block';const canvas=document.querySelector('#maze-map'),ctx=canvas.getContext('2d'),cell=canvas.width/MAZE_SIZE;ctx.fillStyle='#100a07';ctx.fillRect(0,0,canvas.width,canvas.height);for(let y=0;y<MAZE_SIZE;y++)for(let x=0;x<MAZE_SIZE;x++){ctx.fillStyle=mazeGrid[y][x]?'#3f2818':'#9a7950';ctx.fillRect(x*cell,y*cell,Math.ceil(cell),Math.ceil(cell))}const [px,py]=mazeCell(camera.position);ctx.fillStyle='#f3e5bd';ctx.beginPath();ctx.arc((px+.5)*cell,(py+.5)*cell,cell*.42,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#17100b';ctx.lineWidth=1;ctx.stroke();ctx.fillStyle='#65a06c';ctx.fillRect((1+.2)*cell,(1+.2)*cell,cell*.6,cell*.6);const exit=MAZE_SIZE-2,pulse=.42+Math.sin(performance.now()/180)*.12;ctx.fillStyle='#e0372b';ctx.beginPath();ctx.arc((exit+.5)*cell,(exit+.5)*cell,cell*pulse,0,Math.PI*2);ctx.fill()}

document.querySelectorAll('#rooms button').forEach(b=>b.onclick=()=>tryChangeRoom(+b.dataset.room));
document.addEventListener('keydown',e=>{if((e.code==='Space'||e.code==='KeyC'||e.code==='ControlLeft'||e.code==='ControlRight')&&!chaseControlsActive()){if(e.code==='Space')e.preventDefault();return}keys[e.code]=true;if(activeStory==='cabin'&&/^Digit[1-8]$/.test(e.code)&&!combat)tryChangeRoom(+e.code.slice(-1)-1);if(e.code==='KeyE')interact();if(e.code==='KeyF')swingBat();if(e.code==='Space'){e.preventDefault();jumpPlayer()}});document.addEventListener('keyup',e=>keys[e.code]=false);
canvas.onclick=()=>{if(!controls.isLocked&&!dlg.open&&!intro.open)controls.lock();else if(combat)swingBat();else if(controls.isLocked)interact()};
function interact(){const ray=new THREE.Raycaster();ray.setFromCamera(new THREE.Vector2(),camera);const hit=ray.intersectObjects(interactables)[0];if(hit&&hit.distance<4.5){const data=hit.object.userData;if(data.type==='fun-pickup')collectFunPickup(hit.object);else if(data.type==='story-choice')chooseStory(data.part);else if(data.type==='jailbreak')handleJailbreak(data.part);else if(data.type==='handle')collectHandle(data.part,hit.object);else if(data.type==='door')enterDoor(data.part);else if(data.type==='bat')collectBat();else if(data.type==='creature')startCombat();else if(data.type==='bonus')openBonusPuzzle(data.part);else if(data.type==='cabin-secret')openCabinSecret(data.part);else if(data.type==='hotel-person')talkToHotelPerson(data.part);else if(data.type==='hotel-elevator-button')pressHotelElevatorButton(data.part);else if(data.type==='hotel-painting')inspectHotelPainting();else if(data.type==='hotel-feature')inspectHotelFeature(data.part);else if(data.type==='hotel-door')chooseHotelDoor(data.part,hit.object);else if(data.type==='hotel-elevator')openHotelElevator();else if(data.type==='hotel-run-search'||data.type==='hotel-run-exit'||data.type==='hotel-run-hide'||data.type==='hotel-run-boss')handleHotelRun(data.part===-1?data.type:data.part);else if(data.type==='hotel-stage')handleHotelStage(data.part);else openPuzzle(data.room)}}
function rootMazeRequirements(){const chapters=saved.slice(0,7).filter(Boolean).length,hidden=requiredBonusPuzzles.filter(id=>bonusSolved.has(id)).length,secrets=requiredCabinSecrets.filter(id=>cabinSecrets.has(id)).length;return{chapters,hidden,secrets,complete:chapters===7&&hidden===requiredBonusPuzzles.length&&secrets===requiredCabinSecrets.length}}
function tryChangeRoom(target){if(activeStory!=='cabin'){return false}if(target<0||target>7)return false;if(target===7){const gate=rootMazeRequirements();if(!gate.complete){controls.unlock();message('THE ROOT CHAMBER IS SEALED',`The roots demand every secret first. Chapter puzzles: ${gate.chapters}/7 · Hidden puzzles: ${gate.hidden}/6 · Cabin secrets: ${gate.secrets}/7. Return to the unfinished rooms.`);return false}}if(combat)stopCombat();room=target;buildRoom(room);return true}
function crossDoorway(){if(doorTransitionCooldown>0||inLobby||room>=7)return;const doorway=doorways.find(door=>door.side==='back'?camera.position.z<-5.72&&Math.abs(camera.position.x)<1.1:door.side==='right'?camera.position.x>door.threshold&&Math.abs(camera.position.z+2)<1.1:camera.position.x<-door.threshold&&Math.abs(camera.position.z+2)<1.1);if(!doorway)return;if(doorway.locked){const limit=doorway.threshold-.18;if(doorway.side==='back')camera.position.z=-5.5;else camera.position.x=doorway.side==='right'?limit:-limit;doorTransitionCooldown=.8;controls.unlock();message(room===0?'THE HANDLE IS BROKEN':'THE ROOT CHAMBER IS SEALED',room===0?'Find all three brass pieces before crossing this threshold.':'The roots will not let you pass until the cabin has surrendered every secret.');return}const previousRoom=room;doorArrival={from:previousRoom};doorTransitionCooldown=1;if(tryChangeRoom(doorway.target)){document.querySelector('#prompt').textContent=`YOU CROSSED INTO ${rooms[room][1].toUpperCase()} · TURN BACK AT ANY TIME`;controls.lock()}}
function saveHotelProgress(id){hotelProgress.add(id);localStorage.setItem('infinite-hotel-progress',JSON.stringify([...hotelProgress]))}
function advanceHotelStage(name,copy){hotelStage++;localStorage.setItem('infinite-hotel-stage',hotelStage);saveHotelProgress(`stage-${hotelStage}`);buildRoom(8);controls.unlock();message(name,copy)}
function hotelButtonPuzzle(name,copy,buttons,correct){controls.unlock();base('THE INFINITE HOTEL',name,copy);let chosen=[];const wrap=document.createElement('div');wrap.className='choices';buttons.forEach(label=>{const button=document.createElement('button');button.textContent=label;button.onclick=()=>{chosen.push(label);feedback.textContent=chosen.join(' → ');if(chosen.length===correct.length){if(chosen.join()===correct.join())setTimeout(()=>hotelStage===9?finishHotel():advanceHotelStage('THE HOTEL ACCEPTS THE RULE','The room folds inward and becomes somewhere impossible.'),450);else{feedback.textContent='The hotel learned that answer. The room resets.';setTimeout(()=>hotelButtonPuzzle(name,copy,buttons,correct),850)}}};wrap.append(button)});body.append(wrap)}
function animateElevatorOpen(){if(hotelDoorAnimating)return;hotelDoorAnimating=true;dlg.close();const left=roomGroup.getObjectByName('elevator left door'),right=roomGroup.getObjectByName('elevator right door'),portal=roomGroup.getObjectByName('elevator interior'),leftStart=left.position.x,rightStart=right.position.x,started=performance.now(),duration=1300;portal.visible=true;document.querySelector('#prompt').textContent='THE ELEVATOR IS OPENING';function frame(now){const t=Math.min(1,(now-started)/duration),ease=t<.5?2*t*t:1-Math.pow(-2*t+2,2)/2;left.position.x=leftStart-ease*2.45;right.position.x=rightStart+ease*2.45;portal.material.emissiveIntensity=1.5+Math.sin(t*Math.PI)*2;if(t<1)requestAnimationFrame(frame);else setTimeout(()=>{hotelDoorAnimating=false;advanceHotelStage('THE ELEVATOR ARRIVES','The brass doors reveal a car much deeper than the building. The panel has no ordinary floors.')},350)}requestAnimationFrame(frame)}
function hotelElevatorPuzzle(){controls.unlock();base('THE INFINITE HOTEL','THE BRASS ELEVATOR','The indicator is blank. Press the four impossible floors in the order engraved above the doors.');const correct=['13','-4','½','∞'],buttons=['13','-4','½','∞'],chosen=[],wrap=document.createElement('div');wrap.className='choices';buttons.forEach(label=>{const button=document.createElement('button');button.textContent=label;button.onclick=()=>{chosen.push(label);button.classList.add('used');feedback.textContent=chosen.join(' → ');if(chosen.length===correct.length){if(chosen.join()===correct.join()){feedback.textContent='A bell rings somewhere far above you.';setTimeout(animateElevatorOpen,500)}else{feedback.textContent='The indicator flashes 0. The doors remain shut.';setTimeout(hotelElevatorPuzzle,900)}}};wrap.append(button)});body.append(wrap)}
