let introStep=0;document.body.classList.add('intro-mode');function enterGameFromIntro(){const blackout=document.querySelector('#blackout');intro.close();document.body.classList.remove('intro-mode');room=0;buildRoom(0);blackout.querySelector('span').textContent='You wake inside the cabin.';blackout.classList.add('show');controls.lock();setTimeout(()=>blackout.classList.remove('show'),900)}document.querySelector('#enter').onclick=()=>{introStep++;if(introStep===1){document.querySelector('#intro-kicker').textContent='NO ROAD FOR MILES';document.querySelector('#intro-title').innerHTML='Two lights appear<br><em>between the trees.</em>';document.querySelector('#intro-copy').textContent='One resembles a cabin window. The other looks like a hotel sign that could not possibly be here.';document.querySelector('#enter').textContent='KEEP WALKING'}else if(introStep===2){document.querySelector('#intro-title').innerHTML='The forest goes silent.<br><em>Both doors open.</em>';document.querySelector('#intro-copy').textContent='Something behind you makes the choice feel urgent.';document.querySelector('#enter').textContent='ENTER THE CABIN'}else enterGameFromIntro()};try{intro.showModal()}catch{intro.setAttribute('open','')}buildForest();animate();addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)});renderer.setSize(innerWidth,innerHeight);
